"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod/v3";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Building01Icon, Tag01Icon, ArrowRight01Icon, ArrowLeft01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";

const workspaceSchema = z.object({
  workspaceName: z.string().min(2, "Workspace name is required."),
  industry: z.string().min(1, "Please select an industry."),
  workspaceRole: z.string().min(1, "Please select your role."),
});

type WorkspaceValues = z.infer<typeof workspaceSchema>;

interface WorkspaceStepProps {
  onNext: (data: WorkspaceValues) => void;
  onBack: () => void;
  defaultValues: Partial<WorkspaceValues>;
}

export const WorkspaceStep = ({ onNext, onBack, defaultValues }: WorkspaceStepProps) => {
  const form = useForm<WorkspaceValues>({
    resolver: zodResolver(workspaceSchema),
    defaultValues: {
      workspaceName: defaultValues.workspaceName || "",
      industry: defaultValues.industry || "",
      workspaceRole: defaultValues.workspaceRole || "",
    },
  });

  return (
    <div className="space-y-6">
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onNext)} className="space-y-4">
          <FormField
            control={form.control}
            name="workspaceName"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Workspace Name</FormLabel>
                <FormControl>
                  <div className="relative group">
                     <HugeiconsIcon icon={Building01Icon} className="absolute left-2.5 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground transition-colors group-focus-within:text-primary" />
                     <Input className="pl-8 h-8 transition-all" placeholder="Acme Inc." {...field} />
                  </div>
                </FormControl>
                <FormMessage className="text-[10px]" />
              </FormItem>
            )}
          />

          <div className="grid grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="industry"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Industry</FormLabel>
                  <Select onValueChange={field.onChange} defaultValue={field.value}>
                    <FormControl>
                      <SelectTrigger className="w-full pl-8 h-8 text-xs relative">
                         <HugeiconsIcon icon={Tag01Icon} className="absolute left-2.5 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground" />
                         <SelectValue placeholder="Industry" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="tech">Technology</SelectItem>
                      <SelectItem value="marketing">Marketing</SelectItem>
                      <SelectItem value="finance">Finance</SelectItem>
                      <SelectItem value="education">Education</SelectItem>
                      <SelectItem value="other">Other</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage className="text-[10px]" />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="workspaceRole"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Your Role</FormLabel>
                  <Select onValueChange={field.onChange} defaultValue={field.value}>
                    <FormControl>
                      <SelectTrigger className="w-full h-8 text-xs">
                        <SelectValue placeholder="Role" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="owner">Founder / Owner</SelectItem>
                      <SelectItem value="manager">Manager</SelectItem>
                      <SelectItem value="developer">Developer</SelectItem>
                      <SelectItem value="designer">Designer</SelectItem>
                      <SelectItem value="other">Other</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage className="text-[10px]" />
                </FormItem>
              )}
            />
          </div>

          <div className="flex gap-3 pt-4">
            <Button type="button" variant="outline" className="flex-1" size="lg" onClick={onBack}>
               <HugeiconsIcon icon={ArrowLeft01Icon} className="mr-2" size={18} />
               Back
            </Button>
            <Button type="submit" className="flex-1" size="lg">
               Next Step
               <HugeiconsIcon icon={ArrowRight01Icon} className="ml-2" size={18} />
            </Button>
          </div>
        </form>
      </Form>
    </div>
  );
};
